// 只送固定欄位：workflow 名稱、失敗節點名稱（限定在已知節點）、執行編號、時間。
// 錯誤訊息與堆疊一律不讀、不送：SSH 或 Code 節點的錯誤訊息可能整段包含使用者的問題。
const KNOWN_WORKFLOWS = ["My workflow", "PSF EIM QA Approval"];
const KNOWN_NODES = ["Build Decision Score", "Build Pending-Review Tag", "Code in JavaScript", "Encode Question", "Execute a command", "Form", "IF needs_review", "IF valid", "Log to Langfuse", "On form submission", "QA Deterministic Checks", "QA LLM Judge", "QA Parse & Threshold", "Respond Error", "Respond OK", "Send Decision to Langfuse", "Send QA Scores to Langfuse", "Tag Pending Review", "Webhook"];

const e = $input.item.json;
const wf = e.workflow || {};
const ex = e.execution || {};
const workflow_name = KNOWN_WORKFLOWS.includes(wf.name) ? wf.name : 'unknown';
const failed_node = KNOWN_NODES.includes(ex.lastNodeExecuted) ? ex.lastNodeExecuted : 'unknown';
const execution_id = /^[0-9]{1,12}$/.test(String(ex.id)) ? String(ex.id) : 'unknown';

const hex = (len) => Array.from({ length: len }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const nowMs = Date.now();

const langfuse_body = {
  resourceSpans: [
    {
      resource: {
        attributes: [
          { key: "service.name", value: { stringValue: "psf-eim-rag-n8n" } }
        ]
      },
      scopeSpans: [
        {
          scope: { name: "n8n-psf-eim-rag" },
          spans: [
            {
              traceId: hex(32),
              spanId: hex(16),
              name: "psf_eim_workflow_error",
              kind: 1,
              startTimeUnixNano: `${nowMs}000000`,
              endTimeUnixNano: `${nowMs}000000`,
              attributes: [
                { key: "langfuse.trace.name", value: { stringValue: "psf-eim-workflow-error" } },
                { key: "langfuse.observation.level", value: { stringValue: "ERROR" } },
                { key: "langfuse.observation.metadata.workflow_name", value: { stringValue: workflow_name } },
                { key: "langfuse.observation.metadata.failed_node", value: { stringValue: failed_node } },
                { key: "langfuse.observation.metadata.execution_id", value: { stringValue: execution_id } },
                { key: "langfuse.observation.metadata.source", value: { stringValue: "n8n" } }
              ],
              status: { code: 2 }
            }
          ]
        }
      ]
    }
  ]
};

return { langfuse_body };
